import { Buffer } from 'node:buffer';

const origin = 'https://jorgefelipecastro-debug.github.io';
const maxBytes = 15 * 1024 * 1024;
const fleet = 'flota@allzonelogistics.com';
const email = v => /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(v) && v.length <= 254;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const cors = {
  'Access-Control-Allow-Origin': origin,
  'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
  'Access-Control-Allow-Headers': 'content-type,x-recipient,x-filename,x-plate-a,x-plate-b,x-accident-date,x-accident-place,x-mail-batch-id,x-turnstile-token',
  'Cache-Control': 'no-store',
};
const reply = (status, body) => Response.json(body, {status, headers: cors});

const TEST = Symbol();
const worker = {
  async fetch(req, env, mode) {
    if (new URL(req.url).pathname === '/prueba-correo') return runMailTest(req, env);
    const isTest = mode === TEST;
    if (new URL(req.url).pathname !== '/send-accident-report') return reply(404, {ok:false});
    if (req.headers.get('origin') !== origin) return reply(403, {ok:false});
    if (req.method === 'OPTIONS') return new Response(null, {status:204, headers:cors});
    if (!env.BREVO_API_KEY || !email(env.BREVO_SENDER || '') || !env.TURNSTILE_SECRET || !env.RATE_LIMITER)
      return reply(503, {ok:false, error:'primary_not_configured', noDelivery:true, fallback:true});
    if (req.method === 'GET') return reply(200, {ok:true, ready:true});
    if (req.method !== 'POST') return reply(405, {ok:false});
    const h = name => req.headers.get(name) || '';
    const recipient = h('x-recipient').trim().toLowerCase();
    const batch = h('x-mail-batch-id');
    const token = h('x-turnstile-token');
    if (!email(recipient) || !uuid.test(batch) || h('content-type') !== 'application/pdf')
      return reply(400, {ok:false,error:'invalid_report',noDelivery:true});
    if (!token || token.length > 2048) return reply(403, {ok:false,error:'verification_required',noDelivery:true});
    const ip = h('cf-connecting-ip');
    try {
      if (!ip || !(await env.RATE_LIMITER.limit({key:ip})).success)
        return reply(429, {ok:false,error:'rate_limited',noDelivery:true});
      const verify = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
        method:'POST', body:new URLSearchParams({secret:env.TURNSTILE_SECRET,response:token,remoteip:ip}),
        signal:AbortSignal.timeout(8000),
      });
      const checked = await verify.json();
      if (!verify.ok || !checked.success || checked.hostname !== (isTest ? testHost : new URL(origin).hostname) || checked.action !== 'accident_mail')
        return reply(403, {ok:false,error:'verification_failed',noDelivery:true});
    } catch { return reply(503, {ok:false,error:'verification_unavailable',noDelivery:true}); }

    let payload;
    let recipients;
    try {
      if (Number(h('content-length')) > maxBytes) return reply(413, {ok:false,error:'attachment_too_large',noDelivery:true});
      const reader = req.body?.getReader();
      if (!reader) return reply(400, {ok:false,error:'invalid_attachment',noDelivery:true});
      const chunks = [];
      let size = 0;
      while (true) {
        const {value, done} = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > maxBytes) { await reader.cancel(); return reply(413, {ok:false,error:'attachment_too_large',noDelivery:true}); }
        chunks.push(value);
      }
      const pdf = Buffer.concat(chunks, size);
      if (pdf.subarray(0,5).toString('ascii') !== '%PDF-')
        return reply(400, {ok:false,error:'invalid_attachment',noDelivery:true});
      const filename = (h('x-filename') || 'PARTE_COMPLETO_ALLZONE.pdf').replace(/[^A-Za-z0-9._-]/g,'_').slice(0,120);
      const a = h('x-plate-a').slice(0,30), b = h('x-plate-b').slice(0,30);
      const place = decodeURIComponent(h('x-accident-place')).slice(0,240);
      const date = h('x-accident-date').slice(0,40);
      recipients = [...new Set([env.TEST_FLEET || fleet, recipient])];
      payload = JSON.stringify({
        sender:{name:'Allzone Logistics',email:env.BREVO_SENDER},
        replyTo:{email:env.TEST_FLEET || fleet},
        subject:[isTest ? 'PRUEBA — NO TRAMITAR | Parte de accidente Allzone' : 'Parte de accidente Allzone',a && 'A '+a,b && 'B '+b].filter(Boolean).join(' · '),
        textContent:[isTest && 'PRUEBA — NO TRAMITAR. Parte de accidente ficticio.', 'Adjuntamos el parte completo del accidente, con la ubicación y las fotografías.',a && 'Vehículo A: '+a,b && 'Vehículo B: '+b,date && 'Fecha: '+date,place && 'Lugar: '+place].filter(Boolean).join('\n'),
        headers:{idempotencyKey:batch},
        messageVersions:[{to:recipients.map(email=>({email}))}],
        attachment:[{name:filename,content:pdf.toString('base64')}],
      });
    } catch { return reply(400, {ok:false,error:'invalid_report',noDelivery:true}); }
    try {
      const sent = await fetch('https://api.brevo.com/v3/smtp/email',{
        method:'POST',headers:{'api-key':env.BREVO_API_KEY,'Content-Type':'application/json','Accept':'application/json'},
        body:payload,signal:AbortSignal.timeout(40000),
      });
      const result = await sent.json().catch(()=>null);
      if (sent.ok && (result?.messageId || result?.messageIds?.length))
        return reply(200,{ok:true,recipients,provider:'brevo',...(isTest ? {ids:result.messageIds || [result.messageId]} : {})});
      // Brevo can queue mail at its free daily limit. Never switch on quota, duplicate or uncertain responses.
      if (sent.status === 401 || sent.status === 403)
        return reply(502,{ok:false,error:'provider_authorization_rejected',noDelivery:true,fallback:true});
      return reply(502,{ok:false,error:'delivery_unknown'});
    } catch { return reply(504,{ok:false,error:'delivery_unknown'}); }
  }
};

export default worker;

const testHost='parte-accidente-mailer.jorgefelipecastro.workers.dev';
const testExpires=1794842403259;
const testDigest='a01fd8d386b6f62310f308ccabd4037ecd0afb72597f86e4d8784807382dbdeb';
const testBatch='7bdef608-8dc4-4ea3-91bd-a9256b1c8360';
const testPdf='';

async function runMailTest(req,env) {
  if(Date.now()>testExpires || new URL(req.url).hostname!==testHost)
    return reply(404,{ok:false,error:'Prueba cerrada'});
  if(req.method==='GET') return new Response(`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prueba de correo Allzone</title>
  <main><h1>Prueba de correo Allzone</h1><p>Se enviará un parte ficticio marcado «PRUEBA — NO TRAMITAR» a Flota y al Gmail acordado.</p><div id="check"></div><button id="send" disabled>Enviar parte ficticio</button><p id="status" role="status">Cargando la verificación…</p></main>
  <script>
  const pass=location.hash.slice(1);history.replaceState(null,'',location.pathname);
  let token=null;const btn=document.getElementById('send'),info=document.getElementById('status');
  window.initCheck=()=>{if(!pass){info.textContent='Abre el enlace completo que recibiste.'; return;}
  turnstile.render('#check',{sitekey:'0x4AAAAAAGDhuPmmWiu4wSJK',action:'accident_mail',
   callback:v=>{token=v;btn.disabled=false;info.textContent='Listo para enviar.';},
   'expired-callback':()=>{token=null;btn.disabled=true;info.textContent='Verificación caducada. Abre el enlace de nuevo.';}});};
  btn.onclick=async()=>{btn.disabled=true;info.textContent='Enviando…';try{
    const res=await fetch(location.pathname,{method:'POST',headers:{'x-test-pass':pass,'x-turnstile-token':token}});
    const body=await res.json();
    info.textContent=body.ok?'Brevo ha aceptado el envío. Identificador: '+body.ids.join(', '):'No se confirmó el envío: '+(body.error||res.status)+'.';
  }catch{info.textContent='No se pudo confirmar el resultado. No repitas sin comprobar el correo.';}};
  </script><script src="https://challenges.cloudflare.com/turnstile/v0/api.js?onload=initCheck&render=explicit" defer></script></html>`,
    {headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex','X-Frame-Options':'DENY'}});
  if(req.method!=='POST' || req.headers.get('origin')!=='https://'+testHost) return reply(403,{ok:false,error:'Acceso no permitido'});
  const pass=req.headers.get('x-test-pass')||'';
  if(pass.length!==32) return reply(403,{ok:false,error:'Acceso no permitido'});
  const hash=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(pass))).toString('hex');
  if(hash!==testDigest) return reply(403,{ok:false,error:'Acceso no permitido'});
  return worker.fetch(new Request(origin+'/send-accident-report',{method:'POST',headers:{
    origin,'Content-Type':'application/pdf','x-recipient':'jorgefelipecastro@gmail.com',
    'x-filename':'PRUEBA-NO-TRAMITAR.pdf','x-mail-batch-id':testBatch,
    'x-turnstile-token':req.headers.get('x-turnstile-token')||'',
    'cf-connecting-ip':req.headers.get('cf-connecting-ip')||''
  },body:Buffer.from(testPdf,'base64')}),env,TEST);
}
